{"content": "#!/usr/bin/env Rscript
# =============================================================================
# Adaptive Rejection Sampling (ARS) - Gilks & Wild (1992)
# =============================================================================
#
# Implements the adaptive rejection sampler for log-concave unnormalized
# density functions. The algorithm constructs piecewise linear upper and
# lower envelopes to the log-density and samples from the lower envelope,
# accepting or rejecting based on the uniform comparison with the true
# (unnormalized) density.
#
# Modular design:
#   - .validate_inputs()         : input checks
#   - .check_log_concavity()     : verify log-concavity of log(f)
#   - .initialize_envelope()     : set up initial abscissae and tangents
#   - .build_envelopes()         : construct upper/lower piecewise-linear envelopes
#   - .sample_from_lower_env()   : sample from the lower envelope
#   - .update_envelope()         : add new abscissa after rejection
#   - ars()                      : primary public interface
#   - test()                     : formal test suite
#
# Reference:
#   Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for Gibbs
#   sampling. Journal of the Royal Statistical Society: Series C, 41(2), 337-348.
# =============================================================================

# =============================================================================
# INTERNAL: Input Validation
# =============================================================================

.validate_inputs <- function(n, logdens, lower, upper, xstart = NULL) {
  "Validate all inputs to the ARS sampler.

  Args:
    n:        Number of samples to draw.
    logdens:  Function returning log of the (possibly unnormalized) density.
    lower:    Lower bound of the support (or -Inf).
    upper:    Upper bound of the support (or +Inf).
    xstart:   Initial abscissae (vector) or NULL for automatic selection.

  Returns:
    Invisible NULL on success; throws an error otherwise.
  "
  # --- n -------------------------------------------------------------------
  if (!is.numeric(n) || length(n) != 1 || is.na(n)) {
    stop("ars: 'n' must be a single numeric value.")
  }
  if (n < 0) {
    stop("ars: 'n' must be non-negative.")
  }
  if (n != as.integer(n)) {
    stop("ars: 'n' must be an integer.")
  }

  # --- logdens -------------------------------------------------------------
  if (!is.function(logdens)) {
    stop("ars: 'logdens' must be a function taking a numeric vector and returning a numeric vector.")
  }

  # --- bounds --------------------------------------------------------------
  if (!is.numeric(lower) || length(lower) != 1 || is.na(lower)) {
    stop("ars: 'lower' must be a single numeric value (or -Inf).")
  }
  if (!is.numeric(upper) || length(upper) != 1 || is.na(upper)) {
    stop("ars: 'upper' must be a single numeric value (or +Inf).")
  }
  if (is.finite(lower) && is.finite(upper) && lower >= upper) {
    stop("ars: 'lower' must be strictly less than 'upper'.")
  }

  # --- xstart --------------------------------------------------------------
  if (is.null(xstart)) {
    return(invisible(NULL))
  }
  if (!is.numeric(xstart)) {
    stop("ars: 'xstart' must be a numeric vector or NULL.")
  }
  if (length(xstart) < 3) {
    stop("ars: 'xstart' must contain at least 3 points for ARS initialization.")
  }
  # Check that all starting points lie within the support
  bad <- which((is.finite(lower) & xstart <= lower) | (is.finite(upper) & xstart >= upper))
  if (length(bad) > 0) {
    stop("ars: some 'xstart' values lie outside the support [lower, upper].")
  }
  # Check that logdens is finite at all starting points
  y <- tryCatch(logdens(xstart), error = function(e) NULL)
  if (is.null(y)) {
    stop("ars: 'logdens' threw an error at one or more 'xstart' values.")
  }
  if (!is.finite(y) || !all(is.finite(y))) {
    stop("ars: 'logdens' returned non-finite values at some 'xstart' points.")
  }

  invisible(NULL)
}


# =============================================================================
# INTERNAL: Log-Concavity Check
# =============================================================================

.check_log_concavity <- function(logdens, x, hessian_step = 1e-5) {
  "Check that log(f) is concave on the given grid of x values.

  For a univariate function, concavity is verified by checking that the
  numerical second derivative is non-positive everywhere on the grid.

  Args:
    logdens:      Function returning log-density (scalar input, scalar output).
    x:            Numeric vector of abscissae spanning the support.
    hessian_step: Step size for numerical second-derivative approximation.

  Returns:
    TRUE if log-concave, FALSE otherwise.

  Throws:
    Error if the check cannot be performed (e.g., non-finite values).
  "
  if (length(x) < 3) stop("Need at least 3 points to check log-concavity.")

  # Evaluate log-density
  logf <- suppressWarnings(logdens(x))
  if (!is.finite(logf) || !all(is.finite(logf))) {
    return(FALSE)
  }

  # Numerical second derivative via central differences
  h <- hessian_step
  # First derivative (central)
  f_plus  <- suppressWarnings(logdens(x + h))
  f_minus <- suppressWarnings(logdens(x - h))
  if (!is.finite(f_plus) || !is.finite(f_minus) ||
      !all(is.finite(f_plus)) || !all(is.finite(f_minus))) {
    return(FALSE)
  }
  d1 <- (f_plus - f_minus) / (2 * h)

  # Second derivative (central on first derivative)
  d1_plus  <- suppressWarnings((logdens(x + h + h) - logdens(x + h - h)) / (2 * h))
  d1_minus <- suppressWarnings((logdens(x - h + h) - logdens(x - h - h)) / (2 * h))
  if (!is.finite(d1_plus) || !is.finite(d1_minus) ||
      !all(is.finite(d1_plus)) || !all(is.finite(d1_minus))) {
    return(FALSE)
  }
  d2 <- (d1_plus - d1_minus) / (2 * h)

  # Log-concave requires d2 <= 0 everywhere
  max_d2 <- max(d2, na.rm = TRUE)
  if (is.na(max_d2)) return(FALSE)

  return(max_d2 <= 1e-8)  # small tolerance for numerical error
}


# =============================================================================
# INTERNAL: Initialize Envelope (pre-sample log-density evaluations)
# =============================================================================

.initialize_envelope <- function(logdens, lower, upper, xstart) {
  "Set up the initial set of abscissae and evaluate log-density and slopes.

  The initial abscissae are sorted xstart values. For each abscissa we store
  the log-density value and the slope of the tangent line (used for the upper
  envelope). For points at the boundary of a semi-infinite support, the slope
  is set to +/- Inf so the upper envelope asymptotes correctly.

  Args:
    logdens:  Log-density function.
    lower:    Lower support bound.
    upper:    Upper support bound.
    xstart:   Initial abscissae (sorted numeric vector, length >= 3).

  Returns:
    A list with components:
      x      - abscissae (numeric vector)
      logf   - log-density values at abscissae
      slopes - tangent slopes at abscissae
  "
  x <- sort(as.numeric(xstart))
  n_pts <- length(x)
  logf <- logdens(x)

  if (!is.finite(logf) || !all(is.finite(logf))) {
    stop("ars: log-density is non-finite at some initialization points.")
  }

  # Compute slopes via central differences; handle boundaries
  h <- 1e-6
  slopes <- rep(NA_real_, n_pts)
  for (i in seq_len(n_pts)) {
    if (i == 1) {
      # Right-hand difference for left boundary
      f_right <- logdens(x[i] + h)
      if (!is.finite(f_right)) {
        slopes[i] <- -Inf
      } else {
        slopes[i] <- (f_right - logf[i]) / h
      }
    } else if (i == n_pts) {
      # Left-hand difference for right boundary
      f_left <- logdens(x[i] - h)
      if (!is.finite(f_left)) {
        slopes[i] <- Inf
      } else {
        slopes[i] <- (logf[i] - f_left) / h
      }
    } else {
      f_plus  <- logdens(x[i] + h)
      f_minus <- logdens(x[i] - h)
      if (!is.finite(f_plus) || !is.finite(f_minus)) {
        slopes[i] <- NA_real_
      } else {
        slopes[i] <- (f_plus - f_minus) / (2 * h)
      }
    }
  }

  if (any(is.na(slopes))) {
    stop("ars: could not compute slopes at all abscissae; log-density may be non-smooth.")
  }

  list(x = x, logf = logf, slopes = slopes)
}


# =============================================================================
# INTERNAL: Build Upper and Lower Envelopes
# =============================================================================

.build_envelopes <- function(env) {
  "Construct the piecewise-linear upper and lower envelopes from the current
  abscissae, log-density values, and tangent slopes.

  Upper envelope U(x): for each interval [x[i], x[i+1]], the line connecting
    (x[i], logf[i]) with slope slopes[i] and the line connecting
    (x[i+1], logf[i+1]) with slope slopes[i+1]; take the minimum of the two
    (since the density is log-concave, the tangent at the left point lies
    below the tangent at the right point in the interval, and the upper
    envelope is the lower of the two tangent extensions — i.e., the tighter
    bound).

  Lower envelope L(x): for each interval, the straight line connecting
    (x[i], logf[i]) and (x[i+1], logf[i+1]).

  Args:
    env: List from .initialize_envelope() with components x, logf, slopes.

  Returns:
    A list with components:
      lower_intercept, lower_slope  - coefficients of L(x) per interval
      upper_intercept, upper_slope  - coefficients of U(x) per interval
      x          - abscissae
      logf       - log-density at abscissae
  "
  x <- env$x
  logf <- env$logf
  slopes <- env$slopes
  n_intervals <- length(x) - 1

  lower_intercept <- rep(NA_real_, n_intervals)
  lower_slope     <- rep(NA_real_, n_intervals)
  upper_intercept <- rep(NA_real_, n_intervals)
  upper_slope     <- rep(NA_real_, n_intervals)

  for (i in seq_len(n_intervals)) {
    # --- Lower envelope (secant line) ------------------------------------
    lower_slope[i] <- (logf[i + 1] - logf[i]) / (x[i + 1] - x[i])
    lower_intercept[i] <- logf[i] - lower_slope[i] * x[i]

    # --- Upper envelope (hull of two tangents) ---------------------------
    # Tangent at x[i]:   y = logf[i] + slopes[i]*(x - x[i])
    # Tangent at x[i+1]: y = logf[i+1] + slopes[i+1]*(x - x[i+1])
    # Intersection: logf[i] + slopes[i]*(x - x[i]) = logf[i+1] + slopes[i+1]*(x - x[i+1])
    denom <- slopes[i] - slopes[i + 1]
    if (abs(denom) < 1e-12) {
      # Parallel tangents — use the lower one over the interval
      if (slopes[i] <= slopes[i + 1]) {
        upper_slope[i]     <- slopes[i]
        upper_intercept[i] <- logf[i] - slopes[i] * x[i]
      } else {
        upper_slope[i]     <- slopes[i + 1]
        upper_intercept[i] <- logf[i + 1] - slopes[i + 1] * x[i + 1]
      }
    } else {
      x_int <- (logf[i + 1] - logf[i] + slopes[i] * x[i] - slopes[i + 1] * x[i + 1]) / denom
      if (x_int >= x[i] && x_int <= x[i + 1]) {
        # Intersection lies within the interval — upper envelope is the
        # minimum of the two tangent lines
        y_int <- logf[i] + slopes[i] * (x_int - x[i])
        # Piece is tangent[i] on [x[i], x_int], tangent[i+1] on [x_int, x[i+1]]
        # For sampling we store both pieces
        upper_slope[i]     <- slopes[i]
        upper_intercept[i] <- logf[i] - slopes[i] * x[i]
        # Store the break point and second-piece coeffs separately
        env[[paste0("upper_break_", i)]] <- x_int
        env[[paste0("upper_slope2_", i)]] <- slopes[i + 1]
        env[[paste0("upper_int2_", i)]] <- y_int - slopes[i + 1] * x_int
      } else {
        # Intersection outside interval — use the lower of the two tangent
        # slopes over the whole interval
        if (slopes[i] <= slopes[i + 1]) {
          upper_slope[i]     <- slopes[i]
          upper_intercept[i] <- logf[i] - slopes[i] * x[i]
        } else {
          upper_slope[i]     <- slopes[i + 1]
          upper_intercept[i] <- logf[i + 1] - slopes[i + 1] * x[i + 1]
        }
      }
    }
  }

  env$lower_slope     <- lower_slope
  env$lower_intercept <- lower_intercept
  env$upper_slope     <- upper_slope
  env$upper_intercept <- upper_intercept

  return(env)
}


# =============================================================================
# INTERNAL: Sample from the Lower Envelope
# =============================================================================

.sample_from_lower_envelope <- function(env, rng = runif) {
  "Draw a candidate from the distribution proportional to exp(L(x)), where L
  is the piecewise-linear lower envelope.

  The procedure:
    1. Compute the area under exp(L(x)) on each interval (trapezoid-exponential
       integral has a closed form).
    2. Select an interval with probability proportional to its area.
    3. Sample uniformly within that interval, then accept with probability
       proportional to exp(L(x)) / (area / width) — equivalently, sample a
       point and use inverse CDF on the exponential of the linear segment.

  Args:
    env:  Envelope list from .build_envelopes().
    rng:  Random uniform generator (for testability).

  Returns:
    A numeric vector of candidate samples.
  "
  x <- env$x
  n_intervals <- length(x) - 1
  areas <- rep(NA_real_, n_intervals)

  for (i in seq_len(n_intervals)) {
    a <- x[i]
    b <- x[i + 1]
    la <- env$lower_intercept[i]
    m  <- env$lower_slope[i]
    # Integral of exp(la + m*(t-a)) from a to b:
    #   = exp(la) * (exp(m*(b-a)) - 1) / m   if m != 0
    #   = exp(la) * (b-a)                     if m == 0
    if (abs(m) < 1e-12) {
      areas[i] <- exp(la) * (b - a)
    } else {
      areas[i] <- exp(la) * (exp(m * (b - a)) - 1) / m
    }
    if (!is.finite(areas[i]) || areas[i] <= 0) {
      areas[i] <- 0
    }
  }

  total_area <- sum(areas)
  if (total_area <= 0 || !is.finite(total_area)) {
    stop("ars: lower envelope has zero or non-finite total area; cannot sample.")
  }

  probs <- areas / total_area

  # Draw interval
  interval_idx <- sample.int(n_intervals, size = 1, prob = probs)
  i <- interval_idx

  a <- x[i]
  b <- x[i + 1]
  la <- env$lower_intercept[i]
  m  <- env$lower_slope[i]

  # Sample from the truncated exponential on [a, b] with density proportional
  # to exp(la + m*(t-a)).
  if (abs(m) < 1e-12) {
    # Uniform on [a, b]
    u <- rng()
    candidate <- a + u * (b - a)
  } else {
    # Inverse CDF for truncated exponential
    F_a <- 0
    F_b <- (exp(m * (b - a)) - 1) / exp(m * (b - a))  # not needed directly
    # CDF: F(t) = (exp(m*(t-a)) - 1) / (exp(m*(b-a)) - 1)
    # Inverse: t = a + log(1 + u*(exp(m*(b-a)) - 1)) / m
    u <- rng()
    candidate <- a + log(1 + u * (exp(m * (b - a)) - 1)) / m
  }

  return(candidate)
}


# =============================================================================
# INTERNAL: Update Envelope with New Abscissa
# =============================================================================

.update_envelope <- function(env, x_new, logf_new, slopes_new) {
  "Insert a new abscissa into the envelope structure, preserving sorted order.

  Args:
    env:        Current envelope list.
    x_new:      New abscissa value.
    logf_new:   Log-density at x_new.
    slopes_new: Tangent slope at x_new.

  Returns:
    Updated envelope list.
  "
  idx <- which.max(env$x >= x_new)  # position to insert
  if (idx == 1 && !is.na(env$x[1]) && env$x[1] >= x_new) {
    idx <- 1
  } else if (idx > length(env$x) || is.na(env$x[idx])) {
    idx <- length(env$x) + 1
  }

  env$x      <- c(head(env$x, idx - 1), x_new, tail(env$x, -(idx - 1)))
  env$logf   <- c(head(env$logf, idx - 1), logf_new, tail(env$logf, -(idx - 1)))
  env$slopes <- c(head(env$slopes, idx - 1), slopes_new, tail(env$slopes, -(idx - 1)))

  # Remove interval-specific upper-envelope break info (will be recomputed)
  for (key in names(env)) {
    if (grepl("^upper_break_|^upper_slope2_|^upper_int2_", key)) {
      env[[key]] <- NULL
    }
  }

  return(env)
}


# =============================================================================
# INTERNAL: Evaluate Log-Density and Slope at a Point
# =============================================================================

.evaluate_logdens_and_slope <- function(logdens, x_val, h = 1e-6) {
  "Evaluate the log-density and its derivative at a single point.

  Args:
    logdens: Log-density function.
    x_val:   Point at which to evaluate.
    h:       Step size for numerical derivative.

  Returns:
    List with 'logf' and 'slope'.
  "
  logf <- logdens(x_val)
  if (!is.finite(logf)) {
    return(list(logf = -Inf, slope = NA_real_))
  }
  f_plus  <- logdens(x_val + h)
  f_minus <- logdens(x_val - h)
  if (!is.finite(f_plus) || !is.finite(f_minus)) {
    slope <- NA_real_
  } else {
    slope <- (f_plus - f_minus) / (2 * h)
  }
  list(logf = logf, slope = slope)
}


# =============================================================================
# PUBLIC: Adaptive Rejection Sampler
# =============================================================================

ars <- function(n, logdens, lower = -Inf, upper = Inf, xstart = NULL,
                rng = runif, max.iter = 10000) {
  "Adaptive Rejection Sampler (Gilks & Wild, 1992).

  Samples from a distribution with log-density 'logdens' over [lower, upper]
  by constructing piecewise-linear upper and lower envelopes around the
  log-density and accepting/rejecting candidates drawn from the lower
  envelope.

  Args:
    n:         Number of samples to generate (non-negative integer).
    logdens:   Function computing log of the (possibly unnormalized) density.
               Must be vectorized (accept and return numeric vectors).
    lower:     Lower bound of the support (default -Inf).
    upper:     Upper bound of the support (default +Inf).
    xstart:    Initial abscissae (numeric vector of length >= 3) or NULL.
               If NULL, points are chosen adaptively near the mode.
    rng:       Random uniform generator function (for reproducibility in tests).
    max.iter:  Maximum number of iterations (candidate draws).

  Returns:
    A numeric vector of length 'n' containing samples from the target
    distribution.

  Stops with an error if:
    - Inputs are invalid.
    - The log-density is not log-concave (detected during envelope checks).
    - max.iter is exceeded without collecting n samples.
  "
  # --- Input validation ---------------------------------------------------
  .validate_inputs(n, logdens, lower, upper, xstart)

  # Handle trivial case
  if (n == 0) {
    return(integer(0))
  }

  # --- Determine initial abscissae ----------------------------------------
  if (is.null(xstart)) {
    # Try to find a mode by evaluating logdens on a grid and picking the max
    if (is.finite(lower) && is.finite(upper)) {
      grid <- seq(lower + (upper - lower) * 0.1,
                  upper - (upper - lower) * 0.1,
                  length.out = 100)
    } else if (is.finite(lower)) {
      grid <- seq(lower + 1, lower + 100, length.out = 100)
    } else if (is.finite(upper)) {
      grid <- seq(upper - 100, upper - 1, length.out = 100)
    } else {
      grid <- seq(-50, 50, length.out = 100)
    }
    grid_vals <- suppressWarnings(logdens(grid))
    valid_idx <- is.finite(grid_vals)
    if (sum(valid_idx) >= 3) {
      best_idx <- which.max(grid_vals[valid_idx])
      best_x <- grid[valid_idx][best_idx]
      # Choose 3 points around the mode
      spread <- abs(best_x - grid[1])
      if (spread < 1e-10) spread <- 1
      xstart <- c(best_x - spread, best_x, best_x + spread)
      # Ensure within bounds
      if (is.finite(lower)) xstart[xstart < lower] <- lower + 1e-6
      if (is.finite(upper)) xstart[xstart > upper] <- upper - 1e-6
    } else {
      stop("ars: could not determine initial abscissae; please provide 'xstart'.")
    }
  }

  xstart <- sort(as.numeric(xstart))

  # --- Initialize envelope ------------------------------------------------
  env <- .initialize_envelope(logdens, lower, upper, xstart)
  env <- .build_envelopes(env)

  # --- Main sampling loop -------------------------------------------------
  samples <- numeric(0)
  iter <- 0

  while (length(samples) < n && iter < max.iter) {
    iter <- iter + 1

    # Draw candidate from lower envelope
    x_cand <- .sample_from_lower_envelope(env, rng)

    # Evaluate log-density and slope at candidate
    ev <- .evaluate_logdens_and_slope(logdens, x_cand)
    logf_cand <- ev$logf
    slope_cand <- ev$slope

    if (!is.finite(logf_cand)) {
      # Candidate outside effective support — reject and add to upper envelope
      if (is.finite(slope_cand)) {
        env <- .update_envelope(env, x_cand, logf_cand, slope_cand)
        env <- .build_envelopes(env)
      }
      next
    }

    if (!is.finite(slope_cand)) {
      # Cannot compute slope; skip
      next
    }

    # Check log-concavity: the slope should be non-increasing.
    # We check by verifying that the new tangent lies below the current upper
    # envelope everywhere (approximately, at the existing abscissae).
    env_upper_at_x <- sapply(env$x, function(xi) {
      # Find which interval xi falls in
      idx <- which(env$x <= xi)
      if (length(idx) == 0) return(-Inf)
      i <- max(idx)
      if (i >= length(env$x)) return(-Inf)
      env$upper_intercept[i] + env$upper_slope[i] * xi
    })
    # The new tangent at x_cand: y = logf_cand + slope_cand * (xi - x_cand)
    new_tangent <- logf_cand + slope_cand * (env$x - x_cand)
    # Log-concavity requires new_tangent <= env_upper_at_x for all existing x
    if (any(new_tangent > env_upper_at_x + 1e-8)) {
      stop("ars: log-density is not log-concave. Aborting sampling.")
    }

    # Acceptance step: accept with prob exp(logf(x) - U(x))
    # Compute upper envelope at candidate
    upper_at_cand <- NA_real_
    for (i in seq_len(length(env$x) - 1)) {
      if (x_cand >= env$x[i] && x_cand <= env$x[i + 1]) {
        # Check if there's a break point in this interval
        break_key <- paste0("upper_break_", i)
        if (!is.null(env[[break_key]])) {
          break_x <- env[[break_key]]
          slope1 <- env$upper_slope[i]
          int1 <- env$upper_intercept[i]
          slope2 <- env[[paste0("upper_slope2_", i)]]
          int2 <- env[[paste0("upper_int2_", i)]]
          if (x_cand <= break_x) {
            upper_at_cand <- int1 + slope1 * x_cand
          } else {
            upper_at_cand <- int2 + slope2 * x_cand
          }
        } else {
          upper_at_cand <- env$upper_intercept[i] + env$upper_slope[i] * x_cand
        }
        break
      }
    }

    if (is.na(upper_at_cand)) {
      # Fallback: use the tangent at the nearest abscissa
      nearest_idx <- which.min(abs(env$x - x_cand))
      upper_at_cand <- env$logf[nearest_idx] +
                       env$slopes[nearest_idx] * (x_cand - env$x[nearest_idx])
    }

    # Acceptance probability: exp(logf(x) - U(x))
    log_accept_prob <- logf_cand - upper_at_cand
    if (log_accept_prob > 0) {
      log_accept_prob <- 0  # should not happen, but guard against numerical error
    }
    u <- rng()
    if (log(u) <= log_accept_prob) {
      # Accepted
      samples <- c(samples, x_cand)
    } else {
      # Rejected — add to envelope for refinement
      env <- .update_envelope(env, x_cand, logf_cand, slope_cand)
      env <- .build_envelopes(env)
    }
  }

  if (length(samples) < n) {
    stop(sprintf("ars: failed to collect %d samples within %d iterations. ",
                 n, max.iter),
         "The log-density may not be log-concave or the support may be ill-defined.")
  }

  return(samples)
}


# =============================================================================
# TESTS
# =============================================================================

test <- function() {
  "Run formal tests for the ARS sampler.

  Tests include:
    1. VALID_INPUTS          — negative/zero/invalid n, bad logdens, bad bounds
    2. NORMAL_SAMPLING       — sample from standard normal, compare to known
    3. EXPONENTIAL_SAMPLING  — sample from Exp(1), compare to known
    4. LOG_CONCAVITY_CHECK   — detect non-log-concave density
    5. BORDER_CASES          — semi-infinite support, zero samples
    6. REPRODUCTIBILITY      — fixed RNG gives same results
    7. VECTORISED_LOGDENS    — logdens handles vector input

  Prints TEST_NAME: PASS or TEST_NAME: FAIL with statistics.
  "
  results <- list()

  # ---------------------------------------------------------------------------
  # Helper: run a test and record result
  # ---------------------------------------------------------------------------
  run_test <- function(name, expr) {
    cat(sprintf("\n--- %s ---\n", name))
    caught <- tryCatch({
      result <- eval(expr, envir = parent.env(environment()))
      if (isTRUE(result)) {
        cat(sprintf("%s: PASS\n", name))
        results[[name]] <- TRUE
      } else {
        cat(sprintf("%s: FAIL (condition not met)\n", name))
        results[[name]] <- FALSE
      }
    }, error = function(e) {
      cat(sprintf("%s: FAIL (%s)\n", name, e$message))
      results[[name]] <- FALSE
      invisible(NULL)
    })
    invisible(results[[name]])
  }

  # ===================================================================
  # TEST 1: VALID_INPUTS
  # ===================================================================
  run_test("VALID_INPUTS", {
    ok <- TRUE
    # Negative n
    ok <- ok && identical(
      tryCatch({ ars(-1, dnorm_log, -Inf, Inf, c(-2, 0, 2)); "ok" },
               error = function(e) "error"), "error")
    # Non-integer n
    ok <- ok && identical(
      tryCatch({ ars(1.5, dnorm_log, -Inf, Inf, c(-2, 0, 2)); "ok" },
               error = function(e) "error"), "error")
    # Non-function logdens
    ok <- ok && identical(
      tryCatch({ ars(1, "not_a_function", -Inf, Inf, c(-2, 0, 2)); "ok" },
               error = function(e) "error"), "error")
    # Bad bounds
    ok <- ok && identical(
      tryCatch({ ars(1, dnorm_log, 5, 2, c(3, 4, 5)); "ok" },
               error = function(e) "error"), "error")
    # xstart outside support
    ok <- ok && identical(
      tryCatch({ ars(1, dnorm_log, 0, Inf, c(-5, -3, -1)); "ok" },
               error = function(e) "error"), "error")
    ok
  })

  # ===================================================================
  # TEST 2: NORMAL_SAMPLING
  # ===================================================================
  run_test("NORMAL_SAMPLING", {
    set.seed(42)
    samples <- ars(n = 5000, logdens = dnorm_log, lower = -Inf, upper = Inf,
                   xstart = c(-2, 0, 2))
    mean_ok <- abs(mean(samples) - 0) < 0.1
    sd_ok   <- abs(sd(samples) - 1) < 0.1
    cat(sprintf("  n = %d, mean = %.4f, sd = %.4f\n", length(samples),
                mean(samples), sd(samples)))
    mean_ok && sd_ok
  })

  # ===================================================================
  # TEST 3: EXPONENTIAL_SAMPLING
  # ===================================================================
  run_test("EXPONENTIAL_SAMPLING", {
    set.seed(42)
    samples <- ars(n = 5000, logdens = dexp_log, lower = 0, upper = Inf,
                   xstart = c(0.1, 0.5, 2.0))
    mean_ok <- abs(mean(samples) - 1.0) < 0.1
    sd_ok   <- abs(sd(samples) - 1.0) < 0.1
    cat(sprintf("  n = %d, mean = %.4f, sd = %.4f\n", length(samples),
                mean(samples), sd(samples)))
    mean_ok && sd_ok
  })

  # ===================================================================
  # TEST 4: LOG_CONCAVITY_CHECK
  # ===================================================================
  run_test("LOG_CONCAVITY_CHECK", {
    # A bimodal (non-log-concave) density should be rejected
    bimodal_logdens <- function(x) {
      log(0.5 * dnorm(x, mean = -2, sd = 0.5) +
           0.5 * dnorm(x, mean =  2, sd = 0.5))
    }
    ok <- identical(
      tryCatch({
        ars(n = 100, logdens = bimodal_logdens, lower = -Inf, upper = Inf,
            xstart = c(-3, 0, 3))
        "ok"
      }, error = function(e) e$message),
      "ars: log-density is not log-concave. Aborting sampling.")
    ok
  })

  # ===================================================================
  # TEST 5: BORDER_CASES
  # ===================================================================
  run_test("BORDER_CASES", {
    ok <- TRUE
    # Zero samples
    z <- ars(n = 0, logdens = dnorm_log, -Inf, Inf)
    ok <- ok && length(z) == 0
    # Semi-infinite support (exponential with lower = 0)
    set.seed(99)
    s <- ars(n = 500, logdens = dexp_log, lower = 0, upper = Inf,
             xstart = c(0.1, 0.5, 2.0))
    ok <- ok && all(s > 0) && mean(s) > 0.5 && mean(s) < 1.5
    ok
  })

  # ===================================================================
  # TEST 6: REPRODUCIBILITY
  # ===================================================================
  run_test("REPRODUCIBILITY", {
    fake_rng <- function(n) rep(0.5, n)
    set.seed(1)
    s1 <- ars(n = 5, logdens = dnorm_log, -Inf, Inf,
              xstart = c(-2, 0, 2), rng = fake_rng)
    s2 <- ars(n = 5, logdens = dnorm_log, -Inf, Inf,
              xstart = c(-2, 0, 2), rng = fake_rng)
    all(s1 == s2)
  })

  # ===================================================================
  # TEST 7: VECTORISED_LOGDENS
  # ===================================================================
  run_test("VECTORISED_LOGDENS", {
    vec_logdens <- function(x) {
      -0.5 * x^2 - 0.5 * log(2 * pi)
    }
    set.seed(7)
    samples <- ars(n = 1000, logdens = vec_logdens, -Inf, Inf,
                   xstart = c(-2, 0, 2))
    mean_ok <- abs(mean(samples) - 0) < 0.15
    sd_ok   <- abs(sd(samples) - 1) < 0.15
    cat(sprintf("  n = %d, mean = %.4f, sd = %.4f\n", length(samples),
                mean(samples), sd(samples)))
    mean_ok && sd_ok
  })

  # ===================================================================
  # SUMMARY
  # ===================================================================
  cat("\n========================================\n")
  passed <- sum(unlist(results))
  total  <- length(results)
  cat(sprintf("Results: %d/%d tests passed\n", passed, total))
  cat("========================================\n")

  # Save normal samples to file for verification
  set.seed(123)
  norm_samples <- ars(n = 1000, logdens = dnorm_log, -Inf, Inf,
                      xstart = c(-2, 0, 2))
  writeLines(as.character(norm_samples), "/app/normal_samples.txt")
  cat("\nSaved 1000 normal samples to /app/normal_samples.txt\n")

  # Save exponential samples to file for verification
  set.seed(123)
  exp_samples <- ars(n = 1000, logdens = dexp_log, 0, Inf,
                     xstart = c(0.1, 0.5, 2.0))
  writeLines(as.character(exp_samples), "/app/exponential_samples.txt")
  cat("Saved 1000 exponential samples to /app/exponential_samples.txt\n")

  return(invisible(results))
}


# =============================================================================
# HELPER: Log-density functions for testing
# =============================================================================

dnorm_log <- function(x) {
  dnorm(x, log = TRUE)
}

dexp_log <- function(x) {
  ifelse(x < 0, -Inf, -x)
}

# =============================================================================
# MAIN
# =============================================================================

if (!interactive()) {
  test()
}
